//! Oracle tests for the path-effect kernel (G13/#2107, leaf L01-A).
//!
//! `fixtures/object-path-effects-kernel/oracle.txt` (`ORACLE`, sha256
//! 1115aee769d625799e53b4e89c063c4efad74af1516c37ab428657185000b677) was generated by `gen.cjs` (sha256
//! 3d05f6821b3f3907e0e5674a4246b2357cab3f3975882c70de0b7dd24b1a76e6, kept outside the repo), which runs
//! `src/js/path-fx.js` of commit fbe4b8a3 (sha256 ca510347da44c13986c8a854e4fcc4f2292f4e6624a66de8ea114b86f8be3e74)
//! verbatim in a Node vm; the only edit is one injected export of the closure-private functions. Rows are
//! `pfx1 <op> ...`; numbers are the IEEE 754 bits in hex (`0` is +0), `!` absent, `^` null, `.` empty.
//! Segments are `px,py,hix,hiy,hox,hoy` joined by `;`, a stroke is `raster/closed/width/tag/segments`, an
//! effect `type:enabled:p1:p2:p3` (`enabled` is `t`, `f`, `^`, `!`), a stack joins effects with `|`, and an
//! output stroke is `=` when the baseline returned its input itself (`===`).
//!
//! Tolerance: `walk`, `rc`, `zig`, `pv`, `round`, `type` and every stack that holds no roughen are compared
//! bit for bit (`-0` included). Only `hash2` (`sin(..) * 43758.5453` amplifies a 1-ulp libm difference by
//! 4.4e4, so up to ~1e-11) and what is built on it are bounded: `HASH_TOL`, `NOISE_TOL` (a convex combination
//! of four hashes, times 2) and `ROUGH_TOL * max(1, amount)` per coordinate. The generator proves that no hash
//! fraction lies within 1e-6 of an integer, so a 1-ulp sin difference cannot flip `floor`.

use super::{
    active_stack, apply, apply_roughen, apply_zigzag, has_any, hash2, param_value, round_corners,
    smooth_noise, walk, PathFxEntry, PathFxStroke, PathSegment, P1, PATH_FX_TYPES,
};
use std::borrow::Cow;
use std::collections::BTreeMap;

#[path = "object_path_effects_kernel_controls.rs"]
mod controls;
#[path = "object_path_effects_kernel_pins.rs"]
mod pins;

use controls::Mutation;

pub(crate) const ORACLE: &str = include_str!("fixtures/object-path-effects-kernel/oracle.txt");
pub(crate) const HASH_TOL: f64 = 4e-11;
pub(crate) const NOISE_TOL: f64 = 1e-10;
pub(crate) const ROUGH_TOL: f64 = 1e-10;

/// The stroke fields the kernel does not read; they must survive an effect.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct Rest {
    pub width: Option<u64>,
    pub tag: String,
}

pub(crate) type Stroke = PathFxStroke<Rest>;

pub(crate) fn hex(t: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(t, 16).expect("hex bits"))
}

pub(crate) fn same(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits() || (a.is_nan() && b.is_nan())
}

fn pair(x: &str, y: &str) -> Option<[f64; 2]> {
    (x != "!").then(|| [hex(x), hex(y)])
}

pub(crate) fn seg(t: &str) -> PathSegment {
    let f: Vec<&str> = t.split(',').collect();
    PathSegment {
        point: [hex(f[0]), hex(f[1])],
        handle_in: pair(f[2], f[3]),
        handle_out: pair(f[4], f[5]),
    }
}

pub(crate) fn segs(t: &str) -> Option<Vec<PathSegment>> {
    match t {
        "!" => None,
        "." => Some(Vec::new()),
        _ => Some(t.split(';').map(seg).collect()),
    }
}

pub(crate) fn stroke(t: &str) -> Stroke {
    let f: Vec<&str> = t.split('/').collect();
    PathFxStroke {
        is_raster: f[0] == "1",
        closed: f[1] == "1",
        segments: segs(f[4]),
        rest: Rest {
            width: (f[2] != "!").then(|| hex(f[2]).to_bits()),
            tag: f[3].to_string(),
        },
    }
}

fn param(t: &str) -> Option<f64> {
    (t != "!" && t != "^").then(|| hex(t))
}

pub(crate) fn fx(t: &str) -> Option<PathFxEntry> {
    if t == "^" {
        return None;
    }
    let f: Vec<&str> = t.split(':').collect();
    Some(PathFxEntry {
        fx_type: f[0].to_string(),
        enabled: match f[1] {
            "t" => Some(true),
            "f" => Some(false),
            _ => None,
        },
        params: [param(f[2]), param(f[3]), param(f[4])],
    })
}

pub(crate) fn stack(t: &str) -> Option<Vec<Option<PathFxEntry>>> {
    match t {
        "^" => None,
        "." => Some(Vec::new()),
        _ => Some(t.split('|').map(fx).collect()),
    }
}

fn frame(t: &str) -> Option<f64> {
    (t != "!").then(|| hex(t))
}

/// One comparison row; the first mismatch is kept so mutated runs can be counted.
struct Check {
    label: String,
    bad: Option<String>,
}

impl Check {
    fn fail(&mut self, what: String) {
        if self.bad.is_none() {
            self.bad = Some(format!("{}: {what}", self.label));
        }
    }

    fn num(&mut self, what: &str, got: f64, want: f64, tol: f64) {
        if !same(got, want) && !(tol > 0.0 && (got - want).abs() <= tol) {
            self.fail(format!("{what}: {got:e} vs {want:e}"));
        }
    }

    fn point(&mut self, what: &str, got: [f64; 2], want: [f64; 2], tol: f64) {
        self.num(what, got[0], want[0], tol);
        self.num(what, got[1], want[1], tol);
    }

    fn handle(&mut self, what: &str, got: Option<[f64; 2]>, want: Option<[f64; 2]>, tol: f64) {
        match (got, want) {
            (None, None) => {}
            (Some(g), Some(w)) => self.point(what, g, w, tol),
            (g, w) => self.fail(format!("{what}: {g:?} vs {w:?}")),
        }
    }

    fn segments(&mut self, got: &[PathSegment], want: &[PathSegment], tol: f64) {
        if got.len() != want.len() {
            return self.fail(format!("{} segments vs {}", got.len(), want.len()));
        }
        for (i, (g, w)) in got.iter().zip(want).enumerate() {
            self.point(&format!("point {i}"), g.point, w.point, tol);
            self.handle(&format!("in {i}"), g.handle_in, w.handle_in, tol);
            self.handle(&format!("out {i}"), g.handle_out, w.handle_out, tol);
        }
    }

    fn stroke(&mut self, got: &Stroke, want: &Stroke, tol: f64) {
        if got.is_raster != want.is_raster || got.closed != want.closed || got.rest != want.rest {
            return self.fail(format!("fields {:?} vs {:?}", got.rest, want.rest));
        }
        match (&got.segments, &want.segments) {
            (Some(g), Some(w)) => self.segments(g, w, tol),
            (None, None) => {}
            _ => self.fail("segments presence".to_string()),
        }
    }
}

pub(crate) fn rough_tol(amount: f64) -> f64 {
    ROUGH_TOL
        * if amount.is_nan() || amount.abs() < 1.0 {
            1.0
        } else {
            amount.abs()
        }
}

/// 0 when the stack holds no roughen (bit-exact), else a bound for noise propagated through the stack.
fn stack_tol(list: &[Option<PathFxEntry>]) -> f64 {
    let live: Vec<&PathFxEntry> = list.iter().flatten().collect();
    if !live.iter().any(|f| f.fx_type == "roughen") {
        return 0.0;
    }
    1e-9 * (1.0 + live.iter().map(|f| param_value(f, P1).abs()).sum::<f64>())
}

fn row_walk(c: &mut Check, t: &[&str], m: Mutation) {
    let (closed, per) = (t[3] == "1", t[4].parse::<usize>().expect("per curve"));
    let mut got = walk(&segs(t[2]).expect("segments"), closed, per);
    m.walk(&mut got, closed);
    let want: Vec<&str> = t[5].split(';').collect();
    if got.len() != want.len() {
        return c.fail(format!("{} samples vs {}", got.len(), want.len()));
    }
    for (g, w) in got.iter().zip(want) {
        let f: Vec<&str> = w.split(',').collect();
        c.point("sample", g.point, [hex(f[0]), hex(f[1])], 0.0);
        c.point("normal", g.normal, [hex(f[2]), hex(f[3])], 0.0);
        if g.index != f[4].parse::<usize>().expect("index") {
            c.fail(format!("index {}", g.index));
        }
    }
}

fn row_rc(c: &mut Check, t: &[&str]) {
    let mut s = segs(t[2]).expect("segments");
    round_corners(&mut s, t[3] == "1");
    c.segments(&s, &segs(t[4]).expect("segments"), 0.0);
}

fn row_effect(c: &mut Check, t: &[&str], m: Mutation) {
    let sd = stroke(t[2]);
    let fxe = m.entry(fx(t[3]).expect("entry"));
    let want = t[t.len() - 1];
    let got = if t[1] == "zig" {
        apply_zigzag(&sd, &fxe)
    } else {
        apply_roughen(&sd, &fxe, frame(t[4]))
    };
    let tol = if t[1] == "zig" {
        0.0
    } else {
        rough_tol(param_value(&fxe, P1))
    };
    match (got.expect("within the sample budget"), want) {
        (None, "=") => {}
        (Some(mut g), w) if w != "=" => {
            m.tail(&sd, &mut g);
            c.stroke(&g, &stroke(w), tol);
        }
        (g, w) => c.fail(format!("returned input: {} vs {w}", g.is_none())),
    }
}

fn row_stack(c: &mut Check, t: &[&str], m: Mutation) {
    let list = m.list(stack(t[2]));
    let kept = active_stack(list.as_deref()).map(|v| {
        let all = list.as_ref().expect("list");
        v.iter()
            .map(|f| {
                all.iter()
                    .position(|e| e.as_ref().is_some_and(|e| std::ptr::eq(e, *f)))
            })
            .map(|p| p.expect("kept entry belongs to the list").to_string())
            .collect::<Vec<_>>()
            .join(",")
    });
    if kept.as_deref().unwrap_or("^") != t[3] {
        c.fail(format!("kept {kept:?} vs {}", t[3]));
    }
    if has_any(list.as_deref()) != (t[4] == "1") {
        c.fail("has_any".to_string());
    }
}

fn row_apply(c: &mut Check, t: &[&str], m: Mutation) {
    let strokes: Vec<Stroke> = if t[2] == "." {
        Vec::new()
    } else {
        t[2].split('~').map(stroke).collect()
    };
    let list = m.list(stack(t[3]));
    let tol = list.as_deref().map_or(0.0, stack_tol);
    let out = apply(&strokes, list.as_deref(), frame(t[4])).expect("within the sample budget");
    let want: Vec<&str> = if t[5] == "." {
        Vec::new()
    } else {
        t[5].split('~').collect()
    };
    if out.len() != want.len() {
        return c.fail(format!("{} strokes vs {}", out.len(), want.len()));
    }
    for (k, (got, w)) in out.iter().zip(want).enumerate() {
        match (got, w) {
            (Cow::Borrowed(p), "=") if std::ptr::eq(*p, &strokes[k]) => {}
            (Cow::Owned(g), w) if w != "=" => c.stroke(g, &stroke(w), tol),
            (g, w) => c.fail(format!(
                "stroke {k}: borrowed={} vs {w}",
                matches!(g, Cow::Borrowed(_))
            )),
        }
    }
}

fn row_pv(c: &mut Check, t: &[&str], m: Mutation) {
    let key = t[3].parse::<usize>().expect("key") - 1;
    let mut params = [None; 3];
    params[key] = param(t[4]);
    // AmountScale scales the roughen amount (params[0]) used by effect rows only; a paramValue row must
    // still read the authored value exactly (tol 0.0), so it runs unmutated.
    let m = if matches!(m, Mutation::AmountScale(_)) {
        Mutation::None
    } else {
        m
    };
    let e = m.entry(PathFxEntry {
        fx_type: t[2].to_string(),
        enabled: None,
        params,
    });
    c.num("paramValue", param_value(&e, key), hex(t[5]), 0.0);
}

#[derive(Default)]
pub(crate) struct Run {
    pub rows: BTreeMap<String, usize>,
    pub bad: Vec<(String, String)>,
}

impl Run {
    pub(crate) fn bad_in(&self, op: &str) -> usize {
        self.bad.iter().filter(|(o, _)| o == op).count()
    }
}

pub(crate) fn run(m: Mutation) -> Run {
    let mut r = Run::default();
    for (n, row) in ORACLE.lines().enumerate() {
        let t: Vec<&str> = row.split(' ').collect();
        assert_eq!(t[0], "pfx1", "line {}", n + 1);
        let mut c = Check {
            label: format!("line {}: {}", n + 1, &row[..row.len().min(100)]),
            bad: None,
        };
        match t[1] {
            "type" => {
                let d = PATH_FX_TYPES
                    .iter()
                    .find(|d| d.id == t[2])
                    .expect("known type");
                for k in 0..3 {
                    c.num("default", d.defaults[k], hex(t[3 + k]), 0.0);
                }
            }
            "round" => c.num("Math.round", m.round(hex(t[2])), hex(t[3]), 0.0),
            "pv" => row_pv(&mut c, &t, m),
            "hash" => c.num("hash2", hash2(hex(t[2]), hex(t[3])), hex(t[4]), HASH_TOL),
            "noise" => c.num(
                "smoothNoise",
                smooth_noise(m.x(hex(t[2])), hex(t[3])),
                hex(t[4]),
                NOISE_TOL,
            ),
            "walk" => row_walk(&mut c, &t, m),
            "rc" => row_rc(&mut c, &t),
            "zig" | "rough" => row_effect(&mut c, &t, m),
            "stack" => row_stack(&mut c, &t, m),
            "apply" => row_apply(&mut c, &t, m),
            op => panic!("unknown oracle op {op}"),
        }
        *r.rows.entry(t[1].to_string()).or_insert(0) += 1;
        if let Some(b) = c.bad {
            r.bad.push((t[1].to_string(), b));
        }
    }
    r
}

#[test]
fn generated_oracle_matches_the_baseline() {
    let r = run(Mutation::None);
    assert!(
        r.bad.is_empty(),
        "{} rows differ:\n{}",
        r.bad.len(),
        r.bad
            .iter()
            .map(|b| b.1.as_str())
            .collect::<Vec<_>>()
            .join("\n")
    );
    let counts: Vec<(&str, usize)> = r.rows.iter().map(|(k, v)| (k.as_str(), *v)).collect();
    assert_eq!(
        counts,
        vec![
            ("apply", 35),
            ("hash", 72),
            ("noise", 72),
            ("pv", 72),
            ("rc", 24),
            ("rough", 280),
            ("round", 26),
            ("stack", 13),
            ("type", 2),
            ("walk", 82),
            ("zig", 236),
        ]
    );
}
